"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations

import heapq
from collections import deque


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def _shortest_cycle_through(
    start: str, deps: dict[str, set[str]], dependents: dict[str, list[str]]
) -> list[str] | None:
    if start in deps[start]:
        return [start]

    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for up in dependents[node]:
            if up > start and up not in dist:
                dist[up] = dist[node] + 1
                queue.append(up)

    first = [w for w in deps[start] if w > start and w in dist]
    if not first:
        return None

    steps = min(dist[w] for w in first)
    cycle = [start]
    cur = start
    for need in range(steps, 0, -1):
        cur = min(v for v in deps[cur] if dist.get(v) == need)
        cycle.append(cur)
    return cycle


def _find_cycle(deps: dict[str, set[str]]) -> list[str]:
    dependents: dict[str, list[str]] = {n: [] for n in deps}
    for node, targets in deps.items():
        for target in targets:
            dependents[target].append(node)

    best: list[str] | None = None
    for start in sorted(deps):
        cycle = _shortest_cycle_through(start, deps, dependents)
        if cycle is not None and (best is None or (len(cycle), cycle) < (len(best), best)):
            best = cycle
    assert best is not None
    return best


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    deps: dict[str, set[str]] = {}
    for node, targets in graph.items():
        deps.setdefault(node, set()).update(targets)
        for target in targets:
            deps.setdefault(target, set())

    dependents: dict[str, list[str]] = {n: [] for n in deps}
    for node, targets in deps.items():
        for target in targets:
            dependents[target].append(node)

    pending = {node: len(targets) for node, targets in deps.items()}
    ready = [node for node, count in pending.items() if count == 0]
    heapq.heapify(ready)

    order: list[str] = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for up in dependents[node]:
            pending[up] -= 1
            if pending[up] == 0:
                heapq.heappush(ready, up)

    if len(order) < len(deps):
        raise CycleError(_find_cycle(deps))
    return order
